package com.fixmer.mared.technology.permissions;
import com.fixmer.genesis.technology.permissions.MaopPolicy113;import com.fixmer.genesis.technology.server.firstlaunch.FirstLaunchFiles;import com.fixmer.genesis.technology.server.firstlaunch.LocalApply67;import com.fixmer.genesis.technology.server.remote.*;import com.fixmer.mared.Mared;
import net.minecraft.commands.*;import net.minecraft.network.chat.Component;import net.minecraft.server.MinecraftServer;import net.minecraft.server.level.ServerPlayer;import net.minecraft.world.level.storage.LevelResource;
import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.neoforge.event.RegisterCommandsEvent;import net.neoforged.neoforge.event.server.*;
import com.mojang.brigadier.arguments.StringArgumentType;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;
/** Genuine console grants MaRed roles; /execute as, command blocks, RCON and vanilla OP cannot grant them. */
@EventBusSubscriber(modid=Mared.MOD_ID)
public final class MaopServer113 {
 private static final Map<MinecraftServer,MaopPolicy113> policies=new IdentityHashMap<>();private static final Set<MinecraftServer> ready=Collections.newSetFromMap(new IdentityHashMap<>());private static final Set<MinecraftServer> failed=Collections.newSetFromMap(new IdentityHashMap<>());private static final Map<MinecraftServer,com.fixmer.genesis.technology.permissions.DeviceTrust153> devices153=new IdentityHashMap<>();private static final Map<MinecraftServer,com.fixmer.genesis.technology.permissions.DeviceSessions153> sessions153=new IdentityHashMap<>();private static final Set<MinecraftServer> ready153=Collections.newSetFromMap(new IdentityHashMap<>());
 private MaopServer113(){}
 private static void devices153(MinecraftServer server)throws Exception{if(!devices153.containsKey(server)){var trust=new com.fixmer.genesis.technology.permissions.DeviceTrust153(server.getWorldPath(LevelResource.ROOT).resolve("genesis/maop113"));devices153.put(server,trust);sessions153.put(server,new com.fixmer.genesis.technology.permissions.DeviceSessions153(trust,System::nanoTime));}}
 public static boolean authenticated153(ServerPlayer player){var server=player.getServer();if(server==null||server.getPlayerList().getPlayer(player.getUUID())!=player)return false;if(server.usesAuthentication()||host(player))return true;var sessions=sessions153.get(server);return sessions!=null&&sessions.verified(player.getUUID(),player);}
 public static boolean verifyRequest153(ServerPlayer player,Map<String,String> request)throws Exception{var state=sessions153.get(player.getServer());if(state==null)throw new SecurityException("DENIED");return state.request(player.getUUID(),player,request);}
 public static void rejected153(ServerPlayer player,String request){var state=sessions153.get(player.getServer());if(state!=null)state.rejected(player.getUUID(),player,request);}
 public static String fingerprint153(ServerPlayer player){if(player.getServer()==null||player.getServer().usesAuthentication())return "";var session=sessions153.get(player.getServer());return session==null?"":session.fingerprint(player.getUUID(),player);}
 public static Map<String,String> identity153(ServerPlayer player,Map<String,String> q)throws Exception{var server=player.getServer();devices153(server);var sessions=sessions153.get(server);String op=q.get("op");var result=new TreeMap<String,String>();
  if(op.equals("AUTH_HELLO153"))result.putAll(sessions.begin(player.getUUID(),player,q.get("public")));
  else if(op.equals("AUTH_PROVE153"))sessions.prove(player.getUUID(),player,q.get("ticket"),q.get("proof"));
  else if(!op.equals("AUTH_STATUS153"))throw new IllegalArgumentException("OP");
  result.put("result","OK");result.put("required153",Boolean.toString(!server.usesAuthentication()&&!host(player)));result.put("authenticated153",Boolean.toString(authenticated153(player)));result.putIfAbsent("fingerprint153",fingerprint153(player));result.put("role153",role(player));result.put("controller153",Boolean.toString(remoteReady(server)));return Map.copyOf(result);
 }
 private static int trust153(CommandSourceStack source,String name,String fingerprint,boolean allow){if(!console(source))return 0;try{devices153(source.getServer());UUID target=target(source.getServer(),name);devices153.get(source.getServer()).change(target,fingerprint.toLowerCase(Locale.ROOT),allow);source.sendSuccess(()->Component.translatable(allow?"mared.auth153.trusted":"mared.auth153.revoked",name,fingerprint),false);return 1;}catch(Exception error){source.sendFailure(Component.translatable("mared.auth153.failed"));return 0;}}
 @SubscribeEvent public static void logout153(net.neoforged.neoforge.event.entity.player.PlayerEvent.PlayerLoggedOutEvent event){if(event.getEntity() instanceof ServerPlayer player){var session=sessions153.get(player.getServer());if(session!=null)session.disconnect(player.getUUID(),player);}}

 public static MaopPolicy113 initialize(MinecraftServer s){if(policies.containsKey(s))return policies.get(s);if(failed.contains(s))return null;try{devices153(s);var policy=new MaopPolicy113(s.getWorldPath(LevelResource.ROOT).resolve("genesis/maop113"));policies.put(s,policy);try{bind(s,policy);}catch(Exception legacy){Mared.LOGGER.warn("[Maop113] Remote management disabled: start the server with the updated113 controller",legacy);}return policy;}catch(Exception bad){failed.add(s);Mared.LOGGER.error("[Maop113] Policy unavailable; no remote MaRed authority granted",bad);return null;}}
 private static void bind(MinecraftServer s,MaopPolicy113 policy)throws Exception{String root=System.getenv("GENESIS_DEDICATED74_ROOT");if(root==null)return;var admin=DedicatedAdmin75.open(Path.of(root));Path profile=FirstLaunchFiles.safe(s.getServerDirectory());if(!policy.file.startsWith(profile))throw new java.io.IOException("MAOP113_POLICY_PROFILE");byte[] key=FirstLaunchFiles.read(admin.root.resolve("owner74.key"),32);MaopPolicy113.requireController(key,FirstLaunchFiles.read(admin.root.resolve("controller113"),16384),admin.run);FirstLaunchFiles.write(admin.root.resolve("maop113.binding"),LocalApply67.sign(key,Map.of("schema","113","run",admin.run.toString(),"profile",profile.toString(),"policy",policy.file.toString())),true);FirstLaunchFiles.write(admin.root.resolve("owner113"),LocalApply67.sign(key,Map.of("schema","113","run",admin.run.toString())),true);ready.add(s);var device=devices153.get(s);FirstLaunchFiles.write(admin.root.resolve("maop153.binding"),LocalApply67.sign(key,Map.of("schema","153","run",admin.run.toString(),"profile",profile.toString(),"devices",device.file.toString())),true);
 try{if(LocalApply67.verify(key,FirstLaunchFiles.read(admin.root.resolve("owner153"),16384)).equals(Map.of("schema","153","run",admin.run.toString())))ready153.add(s);}catch(Exception oldOwner){}
 }
 @SubscribeEvent public static void started(ServerStartedEvent e){initialize(e.getServer());}
 @SubscribeEvent public static void stopped(ServerStoppedEvent e){policies.remove(e.getServer());failed.remove(e.getServer());ready.remove(e.getServer());devices153.remove(e.getServer());sessions153.remove(e.getServer());ready153.remove(e.getServer());}
 public static boolean remoteReady(MinecraftServer s){return ready.contains(s)&&(s.usesAuthentication()||ready153.contains(s));}
 public static boolean console(CommandSourceStack source){return source.getEntity()==null&&source.source==source.getServer();}
 private static boolean host(ServerPlayer p){var s=p.getServer();return s!=null&&!s.isDedicatedServer()&&s.getSingleplayerProfile()!=null&&s.getSingleplayerProfile().getId().equals(p.getUUID());}
 public static boolean allowed(ServerPlayer p,String action){var s=p.getServer();if(s==null||s.getPlayerList().getPlayer(p.getUUID())!=p)return false;if(host(p))return MaopPolicy113.ROOT.contains(action);if(!authenticated153(p))return false;var policy=initialize(s);return policy!=null&&policy.state().allows(p.getUUID(),action);}
 public static boolean source(CommandSourceStack source,String action){if(console(source))return true;return source.getEntity() instanceof ServerPlayer p&&source.source==p&&source.getServer().usesAuthentication()&&allowed(p,action);}
 public static Set<String> actions(ServerPlayer p){if(host(p))return MaopPolicy113.ROOT;var policy=initialize(p.getServer());var role=policy==null?null:policy.state().subjects().get(p.getUUID());return role==null?Set.of():MaopPolicy113.RIGHTS.get(role);}
 public static String role(ServerPlayer p){if(host(p))return "ADMIN";var policy=initialize(p.getServer());var role=policy==null?null:policy.state().subjects().get(p.getUUID());return role==null?"NONE":role.name();}
 private static UUID target(MinecraftServer s,String input){var p=s.getPlayerList().getPlayerByName(input);if(p!=null)return p.getUUID();UUID id=UUID.fromString(input.toLowerCase(Locale.ROOT));if(id.equals(new UUID(0,0)))throw new IllegalArgumentException();return id;}
 private static int change(CommandSourceStack source,String name,String role){if(!console(source))return 0;var policy=initialize(source.getServer());if(policy==null){source.sendFailure(Component.translatable("mared.maop113.failed"));return 0;}try{UUID id=target(source.getServer(),name);MaopPolicy113.Role value=role.equals("NONE")?null:MaopPolicy113.Role.valueOf(role);policy.change(id,value,policy.state().revision());source.sendSuccess(()->Component.translatable("mared.maop113.changed",id.toString(),role),false);return 1;}catch(Exception bad){source.sendFailure(Component.translatable("mared.maop113.invalid"));Mared.LOGGER.warn("[Maop113] Console change refused",bad);return 0;}}
 @SubscribeEvent public static void commands(RegisterCommandsEvent e){
  var root=Commands.literal("maop").requires(MaopServer113::console);
  root.then(Commands.literal("list").executes(c->{var policy=initialize(c.getSource().getServer());if(policy==null)return 0;c.getSource().sendSuccess(()->Component.translatable("mared.maop113.list",policy.state().revision(),policy.state().subjects().toString()),false);return 1;}));
  var player=Commands.argument("player",StringArgumentType.word()).executes(c->change(c.getSource(),StringArgumentType.getString(c,"player"),"ADMIN"));
  for(String role:List.of("WORKSPACE","RESTARTER","PUBLISHER","MAINTAINER","ADMIN")){player.then(Commands.literal(role.toLowerCase(Locale.ROOT)).executes(c->change(c.getSource(),StringArgumentType.getString(c,"player"),role)));}
  for(String command:List.of("trust","untrust"))root.then(Commands.literal(command).then(Commands.argument("subject",StringArgumentType.word()).then(Commands.argument("fingerprint",StringArgumentType.word()).executes(c->trust153(c.getSource(),StringArgumentType.getString(c,"subject"),StringArgumentType.getString(c,"fingerprint"),command.equals("trust"))))));
  root.then(player);e.getDispatcher().register(root);e.getDispatcher().register(Commands.literal("madeop").requires(MaopServer113::console).then(Commands.argument("player",StringArgumentType.word()).executes(c->change(c.getSource(),StringArgumentType.getString(c,"player"),"NONE"))));
 }
}
